title: $:/plugins/huwiki/animus-video-export/styles.css
type: text/css
tags: $:/tags/Stylesheet
\*/
.huw-video-export-button{border:1px solid #bca06f!important;background:#d6af70!important;color:#211b14!important;border-radius:6px;min-height:38px;cursor:pointer;padding:7px 12px;font-weight:650}
.huw-video-modal{position:fixed;inset:0;z-index:2147483646;display:flex;align-items:center;justify-content:center;padding:16px;background:rgba(5,13,17,.8);font:14px/1.5 system-ui,-apple-system,BlinkMacSystemFont,sans-serif;color:#f5f5f5}
.huw-video-panel{box-sizing:border-box;background:#172125;color:#f4f3ef;border:1px solid #425056;border-radius:12px;padding:18px;width:min(580px,98vw);max-height:94vh;overflow-y:auto;box-shadow:0 20px 45px rgba(0,0,0,.35);outline:none}
.huw-video-head,.huw-video-actions{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.huw-video-head{justify-content:space-between;border-bottom:1px solid #3a4648;padding-bottom:10px}.huw-video-head strong{font-size:18px}
.huw-video-options{padding:12px 0;display:grid;grid-template-columns:1fr 1fr;gap:12px}
.huw-video-options .huw-video-field{display:flex;flex-direction:column;gap:4px;min-width:0}
.huw-video-options .huw-video-field span{color:#dbd2c0;font-size:12px}
.huw-video-wide{grid-column:1/-1}
.huw-video-field input,.huw-video-field select{width:100%;min-height:37px;box-sizing:border-box;padding:5px 8px;border-radius:5px;background:#fff;color:#172125;border:1px solid #b5c0bf;font:inherit}
.huw-video-range{display:flex;gap:12px;grid-column:1/-1}.huw-video-range .huw-video-field{flex:1}
.huw-video-check{display:flex;align-items:center;gap:9px;grid-column:1/-1;cursor:pointer}.huw-video-check input{width:18px;height:18px;margin:0;accent-color:#dcb46b}
.huw-video-hint{font-size:12px;color:#c1c8c6;grid-column:1/-1;margin:5px 0}
.huw-video-summary{grid-column:1/-1;background:#203237;border:1px solid #40585d;border-radius:8px;padding:10px 12px;font-size:12px;color:#dbe4e2}.huw-video-summary strong{color:#fff}.huw-video-summary p{margin:5px 0 0}.huw-video-summary-names{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;overflow-wrap:anywhere;color:#f3d49a}
.huw-video-output{border-top:1px solid #3a4648;padding:8px 0}.huw-video-output .huw-video-status{margin:8px 0;overflow-wrap:anywhere}
.huw-video-changed{font-size:12px;color:#f4d39b;background:#3b3223;border-radius:6px;padding:8px 10px}.huw-video-changed[hidden]{display:none}
.huw-video-progress{width:100%;height:12px;accent-color:#dcb46b}
.huw-video-files{display:flex;flex-direction:column;gap:6px;margin:10px 0;scroll-margin:12px;border-radius:8px;outline-offset:4px}.huw-video-files:empty{display:none}.huw-video-files:focus-visible{outline:2px solid #d6af70}
.huw-video-files-heading{display:flex;justify-content:space-between;align-items:center;gap:8px}.huw-video-select-all{background:transparent!important;color:#f3d49a!important;border:1px solid #6b7a7c!important;border-radius:5px;padding:4px 8px;min-height:32px;cursor:pointer;font:inherit}
.huw-video-files-title{font-size:16px}.huw-video-files-help{font-size:12px;color:#c1c8c6;margin:0 0 3px}
.huw-video-file-row{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:7px 10px;border:1px solid #41575a;border-radius:8px;background:#203237;min-width:0}.huw-video-file-choice{display:flex;align-items:center;gap:10px;min-width:0;flex:1;cursor:pointer}.huw-video-file-choice input{flex:0 0 20px;width:20px;height:20px;margin:0;accent-color:#d6af70}.huw-video-file-info{min-width:0;display:grid;grid-template-columns:auto 1fr;column-gap:8px;row-gap:1px}.huw-video-file-name{font-size:14px;overflow-wrap:anywhere}.huw-video-file-filename{font-size:11px;color:#b7c4c0;align-self:center;overflow-wrap:anywhere}.huw-video-file-status,.huw-video-file-context{grid-column:1/-1;font-size:11px;color:#c1cecb;overflow-wrap:anywhere}.huw-video-file-context:empty{display:none}.huw-video-file-row[data-current="true"] .huw-video-file-status{color:#afe0b8}.huw-video-file-row[data-ready="true"][data-current="false"] .huw-video-file-status{color:#f3d49a}
.huw-video-files .huw-video-file-download{flex:0 0 44px;width:44px;height:44px;border:1px solid #a98d57;border-radius:7px;background:#d6af70;color:#211b14;cursor:pointer;padding:5px;font:700 26px/1 system-ui,sans-serif}.huw-video-file-download:focus-visible{outline:2px solid white;outline-offset:2px}
.huw-video-files .huw-video-file-download:disabled{opacity:.3;cursor:default;background:#27393e;color:#c1cecb;border-color:#516165}
.huw-video-content{margin:10px 0;border:1px solid #40585d;border-radius:8px;padding:8px 10px}.huw-video-content>summary{cursor:pointer;font-weight:650;color:#dbd2c0}.huw-video-content .huw-video-options{padding:8px 0;gap:8px}.huw-video-content .huw-video-hint{margin:0}
.huw-video-file-metadata{font-size:12px;color:#c1c8c6}.huw-video-file-metadata summary{cursor:pointer;padding:5px 0}.huw-video-file-metadata .huw-video-file-row{margin-top:7px;background:#1a292e}
.huw-video-actions button,.huw-video-close{border-radius:6px;border:1px solid #6b7a7c;padding:8px 12px;min-height:39px;cursor:pointer;background:#27393e;color:white;font:inherit}
.huw-video-actions{position:sticky;bottom:-18px;z-index:2;padding:10px 0 3px;border-top:1px solid #3a4648;background:#172125;box-shadow:0 -8px 10px #172125}.huw-video-actions button[hidden]{display:none}.huw-video-actions .huw-video-primary,.huw-video-actions .huw-video-download-all{background:#d6af70;border-color:#d6af70;color:#221d16;font-weight:700}.huw-video-actions .huw-video-download-all{order:-2}.huw-video-actions .huw-video-primary.huw-video-secondary{display:none}
.huw-video-actions button:disabled{opacity:.5;cursor:default}.huw-video-close{padding:2px 12px;font-size:24px}
@media(max-width:500px){.huw-video-panel{padding:12px}.huw-video-head strong{font-size:16px}.huw-video-actions{bottom:-12px}.huw-video-actions .huw-video-download-all{flex-basis:100%}.huw-video-file-row{gap:8px;padding:7px}.huw-video-file-info{grid-template-columns:1fr}.huw-video-file-filename{display:none}.huw-video-field span{font-size:11px}}
